mapper.select:
SELECT  FROM blog_comment c
JOIN blog_article a ON a.article_id = c.article_id JOIN sys_user u ON u.user_id = c.user_id

    AND c.article_id = #{article}
    AND c.user_id = #{user}
    AND c.status = #{status}
    AND a.author_id = #{author}

ORDER BY c.create_time DESC, c.comment_id DESC

mapper.update:
UPDATE blog_comment c SET c.content = #{comment.content}, c.status = #{comment.status}
WHERE c.comment_id = #{comment.commentId}
AND EXISTS (SELECT 1 FROM blog_article a WHERE a.article_id = c.article_id AND a.author_id = #{author})
AND c.user_id = #{user}
